      if (r.triggerConfig !== undefined) updates.push(`trigger_config = '${JSON.stringify(r.triggerConfig).replace(/'/g, "''")}'::jsonb`);
      if (r.triggerType) updates.push(`trigger_type = '${String(r.triggerType).replace(/'/g, "''")}'`);
