  // PATCH /api/users/me/layout — persist layout preferences
  app.patch("/api/users/me/layout", requireAuth, async (req, res) => {
    const userId = (req.session as any).userId as number;
    const { preferredLayout, widgetVisibility, defaultCommandCenter, widgetOrder, dashboardLayouts, weather } = req.body;

    const VALID_LAYOUTS = ["expanded", "compact"];
    const VALID_CENTERS = ["ceo", "cfo", "cto", "cmo", "sales", "cs", "default", null];

    if (preferredLayout !== undefined && !VALID_LAYOUTS.includes(preferredLayout)) {
      return res.status(400).json({ message: `preferredLayout must be one of: ${VALID_LAYOUTS.join(", ")}` });
    }
    if (defaultCommandCenter !== undefined && !VALID_CENTERS.includes(defaultCommandCenter)) {
      return res.status(400).json({ message: `defaultCommandCenter must be one of: ${VALID_CENTERS.filter(Boolean).join(", ")}` });
    }
    if (widgetVisibility !== undefined && (typeof widgetVisibility !== "object" || Array.isArray(widgetVisibility))) {
      return res.status(400).json({ message: "widgetVisibility must be an object" });
    }
    if (widgetOrder !== undefined && !Array.isArray(widgetOrder)) {
      return res.status(400).json({ message: "widgetOrder must be an array" });
    }
    if (dashboardLayouts !== undefined && (typeof dashboardLayouts !== "object" || Array.isArray(dashboardLayouts))) {
      return res.status(400).json({ message: "dashboardLayouts must be an object" });
    }

    // Weather widget per-user prefs — strict shape, validated before any merge into
    // users.permissions (which also holds role/access data; we never accept arbitrary keys).
    let weatherJsonForMerge: string | undefined;
    if (weather !== undefined) {
      const parsed = weatherPrefsSchema.safeParse(weather);
      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid weather payload", errors: parsed.error.issues });
      }
      const serialized = JSON.stringify(parsed.data);
      if (Buffer.byteLength(serialized, "utf8") > WEATHER_PREFS_MAX_BYTES) {
        return res.status(400).json({ message: "weather payload too large" });
      }
      weatherJsonForMerge = serialized;
    }

    const update: Record<string, any> = {};
    if (preferredLayout !== undefined) update.preferredLayout = preferredLayout;
    if (widgetVisibility !== undefined) update.widgetVisibility = widgetVisibility;
    if (defaultCommandCenter !== undefined) update.defaultCommandCenter = defaultCommandCenter;
    // Persist widgetOrder inside widgetVisibility as __order key
    if (widgetOrder !== undefined) {
      const [existing] = await db.select({ wv: users.widgetVisibility }).from(users).where(eq(users.id, userId)).limit(1);
      const mergedVis = { ...(existing?.wv as Record<string,any> ?? {}), __order: widgetOrder };
      update.widgetVisibility = mergedVis;
    }
    // Persist dashboardLayouts: merge per-centerType (keep other centers untouched)
    if (dashboardLayouts !== undefined) {
      const [existing] = await db.select({ dl: users.dashboardLayouts }).from(users).where(eq(users.id, userId)).limit(1);
      const merged = { ...(existing?.dl as Record<string,any> ?? {}), ...dashboardLayouts };
      update.dashboardLayouts = merged;
    }
    // Persist weather prefs atomically: jsonb_set on the existing JSONB so siblings
    // (mail_team, calendar_team, role grants, etc.) are preserved by construction
    // and there's no read-modify-write race between concurrent requests.
    if (weatherJsonForMerge !== undefined) {
      update.permissions = sql`jsonb_set(coalesce(${users.permissions}, '{}'::jsonb), '{weather}', ${weatherJsonForMerge}::jsonb, true)`;
    }
    if (Object.keys(update).length === 0) return res.status(400).json({ message: "No fields to update" });

    const [updated] = await db.update(users).set(update).where(eq(users.id, userId)).returning({
      preferredLayout: users.preferredLayout,
      widgetVisibility: users.widgetVisibility,
      dashboardLayouts: users.dashboardLayouts,
      defaultCommandCenter: users.defaultCommandCenter,
      permissions: users.permissions,
    });
    res.json(updated);
  });

  // POST /api/users/me/layout/reset — reset dashboard grid layout for a center type
  app.post("/api/users/me/layout/reset", requireAuth, async (req, res) => {
    const userId = (req.session as any).userId as number;
    const { centerType } = req.body ?? {};
    const VALID_CENTERS = ["ceo", "cfo", "cto", "cmo", "sales", "cs", "default"];
    if (!centerType || !VALID_CENTERS.includes(centerType)) {
      return res.status(400).json({ message: `centerType required, one of ${VALID_CENTERS.join(", ")}` });
    }
    const [existing] = await db.select({ dl: users.dashboardLayouts }).from(users).where(eq(users.id, userId)).limit(1);
    const current = (existing?.dl as Record<string, any>) ?? {};
    const next = { ...current };
    delete next[centerType];
    const [updated] = await db.update(users).set({ dashboardLayouts: next }).where(eq(users.id, userId)).returning({
      dashboardLayouts: users.dashboardLayouts,
    });
    res.json(updated);
  });

  app.post("/api/auth/change-password", async (req, res) => {
    if (!req.session?.userId) return res.status(401).json({ message: "Not authenticated" });

    const { currentPassword, newPassword } = req.body;
    if (!currentPassword || !newPassword) return res.status(400).json({ message: "Current and new password required" });
    if (newPassword.length < 6) return res.status(400).json({ message: "New password must be at least 6 characters" });

    const [user] = await db.select().from(users).where(eq(users.id, req.session.userId));
    if (!user) return res.status(404).json({ message: "User not found" });

    const valid = await verifyPassword(currentPassword, user.password);
    if (!valid) return res.status(401).json({ message: "Current password is incorrect" });

    const hashed = await hashPassword(newPassword);
    await db.update(users).set({ password: hashed, mustChangePassword: false }).where(eq(users.id, user.id));

    req.session.mustChangePassword = false;
    res.json({ message: "Password changed successfully" });
  });

