  // ── Attachments ────────────────────────────────────────────────
  // SECURITY (F-09): listing attachments by (objectType, objectId) leaks
  // file metadata (originalName, uploaderName, fileName) for any object the
  // requester can see numerically — even if they have no permission on that
  // section. Gate by the section that owns the linked object before listing.
  app.get("/api/attachments", requireAuth, async (req, res) => {
    const { objectType, objectId } = req.query;
    if (!objectType || !objectId) return res.status(400).json({ message: "objectType and objectId required" });
    const userId = (req.session as any).userId as number;
    const section = attachmentSectionFor(String(objectType));
    const gate = await requireSectionView(userId, section);
    if (!gate.ok) return res.status(403).json({ message: "Not authorized to view attachments for this object" });
    res.json(await storage.getAttachments(objectType as string, Number(objectId)));
  });

  app.post("/api/attachments", requireAuth, (req, res, next) => {
    upload.single("file")(req, res, (err) => {
      if (err) {
        return res.status(400).json({ message: err.message || "Upload failed" });
      }
      next();
    });
  }, async (req, res) => {
    if (!req.file) return res.status(400).json({ message: "No file uploaded" });
    const { objectType, objectId, category, title, notes, tags } = req.body;
    const allowedTypes = ["lead", "account", "partnership", "contact", "opportunity", "quote", "install_workflow", "deployment", "purchase_order", "project", "customer_success", "general", "task", "tradeshow_event"];
    if (!objectType || !objectId || !allowedTypes.includes(objectType)) {
      try { fs.unlinkSync(req.file.path); } catch {}
      return res.status(400).json({ message: "Valid objectType and objectId required" });
    }
    // Commit #5: section-aware edit gate. The GET handler already gates on
    // attachmentSectionFor(objectType) at view-level — POST must require edit
    // on the same section so a viewer cannot upload a file to a record they
    // can only read.
    {
      const userId = (req.session as any).userId as number;
      const role = String((req.session as any).globalRole || "");
      const isAdmin = role === "master_admin" || role === "admin";
      if (!isAdmin) {
        const section = attachmentSectionFor(String(objectType));
        const [u] = await db.select({ permissions: users.permissions })
          .from(users).where(eq(users.id, userId)).limit(1);
        const perms = (u?.permissions as Record<string, string>) || {};
        if ((perms[section] ?? "none") !== "edit") {
          try { fs.unlinkSync(req.file.path); } catch {}
          return res.status(403).json({
            message: `Edit access required on ${section} to upload attachments`,
          });
        }
      }
    }
    try {
      const attachment = await storage.createAttachment({
        objectType,
        objectId: Number(objectId),
        fileName: req.file.filename,
        originalName: req.file.originalname,
        mimeType: req.file.mimetype,
        fileSize: req.file.size,
        uploadedBy: req.session.userId ?? null,
        uploadedByName: req.session.name ?? null,
        category: category ?? "general",
        title: title ?? null,
        notes: notes ?? null,
        tags: tags ? (Array.isArray(tags) ? tags : tags.split(",").map((t: string) => t.trim()).filter(Boolean)) : null,
        source: "upload",
        url: null,
      });
      // Phase 6 — emit activity for notable document categories.
      // Uses parameterized sql`` (NOT sql.raw with string concat) so a malicious
      // filename or title cannot break out of the SQL string.
      const NOTABLE_CATS = ["certification", "contract", "lab_report", "quote_proposal"];
      if (NOTABLE_CATS.includes(attachment.category || "")) {
        const docLabel = attachment.title || attachment.originalName || "document";
        const catLabel = (attachment.category || "general").replace(/_/g, " ");
        const uid = req.session.userId ?? null;
        const summary = `${catLabel} uploaded: ${docLabel}`;
        db.execute(sql`
          INSERT INTO activities (linked_object_type, linked_object_id, type, subject, summary, created_by, created_at)
          VALUES (${objectType}, ${Number(objectId)}, 'activity', 'Important document added', ${summary}, ${uid}, NOW())
        `).catch(() => {});
      }
      res.status(201).json(attachment);
      if (["lead","account","contact"].includes(objectType))
        import("./services/crm-ai-summary").then(m => m.markCrmAiSummaryStale(objectType as any, Number(objectId), "attachment_uploaded")).catch(() => {});
    } catch (e) {
      try { fs.unlinkSync(req.file.path); } catch {}
      res.status(500).json({ message: "Failed to save attachment" });
    }
  });

  app.patch("/api/attachments/:id", requireAuth, async (req, res) => {
    const attachment = await storage.getAttachment(Number(req.params.id));
    if (!attachment) return res.status(404).json({ message: "Attachment not found" });
    const role = String((req.session as any).globalRole || "");
    const isAdmin = ["master_admin", "admin"].includes(role);
    const isOwner = req.session.userId === attachment.uploadedBy;
    if (attachment.uploadedBy !== null && !isAdmin && !isOwner) {
      return res.status(403).json({ message: "Not authorized" });
    }
    const { category, title, notes, tags } = req.body;
    const oldCategory = attachment.category;
    const updated = await storage.updateAttachment(attachment.id, {
      ...(category !== undefined ? { category } : {}),
      ...(title !== undefined ? { title } : {}),
      ...(notes !== undefined ? { notes } : {}),
      ...(tags !== undefined ? { tags: Array.isArray(tags) ? tags : tags.split(",").map((t: string) => t.trim()).filter(Boolean) } : {}),
    });
    // Phase 6 — emit activity when category changes.
    // Parameterized — no sql.raw concat.
    if (category !== undefined && category !== oldCategory) {
      const uid = req.session.userId ?? null;
      const summary = `Category changed from ${oldCategory || "general"} to ${String(category)}`;
      db.execute(sql`
        INSERT INTO activities (linked_object_type, linked_object_id, type, subject, summary, created_by, created_at)
        VALUES (${attachment.objectType}, ${attachment.objectId}, 'activity', 'Document category changed', ${summary}, ${uid}, NOW())
      `).catch(() => {});
    }
    res.json(updated);
  });

  // ── Document Hub endpoints ────────────────────────────────────────────────
  // SECURITY (F-09 follow-up): the Document Hub list endpoint is the same
  // class of cross-record metadata IDOR as /api/attachments — without an ACL
  // any authenticated user can enumerate every uploaded file's metadata
  // (originalName, uploaderName, fileName, linked object_type/object_id,
  // notes, tags) regardless of section permission. Gate by the section that
  // owns the requested objectType filter; for the unfiltered Hub view, fall
  // back to requiring crm:view (11/12 attachment object types map to crm —
  // any user with no CRM access would only see ticket attachments anyway,
  // and they should be looking at /api/tickets/:id/attachments for those).
  app.get("/api/documents", requireAuth, async (req, res) => {
    try {
      const { category, objectType, search, limit, offset } = req.query;
      const userId = (req.session as any).userId as number;
      const section = objectType
        ? attachmentSectionFor(String(objectType))
        : "crm";
      const gate = await requireSectionView(userId, section);
      if (!gate.ok) return res.status(403).json({ message: "Not authorized to view documents" });
      const result = await storage.getAllDocuments({
        category: category as string,
        objectType: objectType as string,
        search: search as string,
        limit: limit ? Number(limit) : 50,
        offset: offset ? Number(offset) : 0,
      });
      res.json(result);
    } catch (e) {
      res.status(500).json({ message: "Failed to load documents" });
    }
  });

  app.post("/api/documents/link", requireAuth, async (req, res) => {
    const { objectType, objectId, url, title, category, notes, tags } = req.body;
    if (!url || !objectType || !objectId) {
      return res.status(400).json({ message: "url, objectType, and objectId are required" });
    }
    const allowedTypes = ["lead", "account", "partnership", "contact", "opportunity", "quote", "install_workflow", "deployment", "purchase_order", "project", "customer_success", "general", "task", "tradeshow_event"];
    if (!allowedTypes.includes(objectType)) {
      return res.status(400).json({ message: "Invalid objectType" });
    }
    try {
      const attachment = await storage.createAttachment({
        objectType,
        objectId: Number(objectId),
        fileName: "",
        originalName: title ?? url,
        mimeType: "text/uri-list",
        fileSize: 0,
        uploadedBy: req.session.userId ?? null,
        uploadedByName: req.session.name ?? null,
        category: category ?? "general",
        title: title ?? null,
        notes: notes ?? null,
        tags: tags ? (Array.isArray(tags) ? tags : tags.split(",").map((t: string) => t.trim()).filter(Boolean)) : null,
        source: "link",
        url,
      });
      // Phase 6 — emit activity for notable linked-document categories.
      // SECURITY (F-08 follow-up): parameterise via drizzle sql`` template
      // (binds values, never concatenates) to prevent SQLi via title/url.
      const NOTABLE_CATS_LINK = ["certification", "contract", "lab_report", "quote_proposal"];
      if (NOTABLE_CATS_LINK.includes(attachment.category || "")) {
        const docLabel = attachment.title || url || "link";
        const catLabel = (attachment.category || "general").replace(/_/g, " ");
        const summary = `${catLabel} link added: ${docLabel}`;
        const uid2 = req.session.userId ?? null;
        const objId = Number(objectId);
        db.execute(sql`INSERT INTO activities (linked_object_type, linked_object_id, type, subject, summary, created_by, created_at) VALUES (${objectType}, ${objId}, 'activity', 'Important document linked', ${summary}, ${uid2}, NOW())`).catch(() => {});
      }
      res.status(201).json(attachment);
    } catch (e) {
      res.status(500).json({ message: "Failed to save link" });
    }
  });

  // SECURITY (F-09): this route streams uploaded files from /uploads.
  // Hardening summary:
  //   1. requireAuth — anonymous file fetches are always rejected.
  //   2. path.basename + UPLOADS_DIR resolve check — defends against path
  //      traversal (../../etc/passwd style payloads).
  //   3. Per-attachment ACL — look the file up in the attachments table,
  //      confirm it exists, and require that the requester is admin OR has
  //      at least `view` permission on the section that gates the linked
  //      object type. Note: an "uploader override" (allow original uploader
  //      regardless of current section permission) was deliberately rejected
  //      during F-09 review: it would re-introduce stale access for users
  //      whose CRM/support permission was later revoked, defeating the
  //      revocation flow. Admin remains the only override.
  //   4. Cache-Control: private, no-store — keeps the body out of any shared
  //      proxy / browser disk cache, in case a logged-out user reuses the
  //      device.
  app.get("/api/attachments/file/:fileName", requireAuth, async (req, res) => {
    const fileName = path.basename(req.params.fileName);
    const filePath = path.join(UPLOADS_DIR, fileName);
    const resolved = path.resolve(filePath);
    if (!resolved.startsWith(UPLOADS_DIR)) return res.status(403).json({ message: "Forbidden" });

    // Per-attachment ACL — uniform 404 for both "no such file" and "no access"
    // so an authenticated user can't enumerate filenames they shouldn't see.
    const userId = (req.session as any).userId as number;
    const role = String((req.session as any).globalRole || "");
    const isAdmin = role === "master_admin" || role === "admin";
    const opaque404 = { message: "File not found" };

    let row: any = null;
    try {
      const r = await db.execute(sql`SELECT id, object_type, object_id, uploaded_by FROM attachments WHERE file_name = ${fileName} LIMIT 1`);
      row = r.rows?.[0] || null;
    } catch (e) {
      console.error("[attachments/file] lookup error:", e);
      return res.status(500).json({ message: "Lookup failed" });
    }
    if (!row && !isAdmin) {
      // No DB record AND not admin → opaque 404. Admin still gets to fetch
      // legacy/orphaned files (covered by file-existence check below).
      return res.status(404).json(opaque404);
    }
    if (row && !isAdmin) {
      // Per F-09 review: NO uploader override — revoked uploaders must lose
      // access alongside everyone else. Admin is the only bypass.
      const section = attachmentSectionFor(String(row.object_type || ""));
      const gate = await requireSectionView(userId, section);
      if (!gate.ok) return res.status(404).json(opaque404);
    }

    if (!fs.existsSync(resolved)) return res.status(404).json(opaque404);
    res.setHeader("Cache-Control", "private, no-store");
    res.sendFile(resolved);
  });

  app.delete("/api/attachments/:id", requireAuth, async (req, res) => {
    const attachment = await storage.getAttachment(Number(req.params.id));
    if (!attachment) return res.status(404).json({ message: "Attachment not found" });
    // Owner-or-admin gate.
    // uploadedBy === null means the record pre-dates ownership tracking → allow as legacy fallback.
    if (attachment.uploadedBy !== null) {
      const role = String((req.session as any).globalRole || "");
      const isAdmin = ["master_admin", "admin"].includes(role);
      const isOwner = req.session.userId === attachment.uploadedBy;
      if (!isAdmin && !isOwner) {
        return res.status(403).json({ message: "Not authorized to delete this attachment" });
      }
    }
    // Phase 6 — log removal activity before deleting the row.
    // SECURITY (F-08): the previous implementation built this INSERT via
    // sql.raw with manual single-quote escaping of `docLabel` — fragile (any
    // future change that drops the .replace, or any new interpolated field
    // that isn't escaped, becomes a SQL-injection sink). Use a parameterised
    // drizzle insert against the typed `activities` table instead — drizzle
    // emits real bound parameters, so no client-side escaping is needed and
    // the column types are checked at compile time.
    const docLabel = attachment.title || attachment.originalName || attachment.fileName || "document";
    const delUid = req.session.userId ?? null;
    db.insert(activities).values({
      linkedObjectType: attachment.objectType,
      linkedObjectId: attachment.objectId,
      type: "activity",
      subject: "Document removed",
      summary: `Removed: ${docLabel}`,
      createdBy: delUid,
    }).then(() => {}).catch(() => {});
    const filePath = path.join(UPLOADS_DIR, path.basename(attachment.fileName));
    try { if (fs.existsSync(filePath)) fs.unlinkSync(filePath); } catch {}
    await storage.deleteAttachment(attachment.id);
    res.json({ message: "Deleted" });
    if (["lead","account","contact"].includes(attachment.objectType ?? "")) {
      import("./services/crm-ai-summary").then(m =>
        m.markCrmAiSummaryStale(attachment.objectType as any, attachment.objectId, "attachment_deleted")
      ).catch(() => {});
    }
  });

  // ── Users List (simple, for dropdowns) ─────────────────────────
  // Auth-gated: returns id/name/email of all users so unauthenticated
  // visitors cannot enumerate the team.
  app.get("/api/users", requireAuth, async (_req, res) => {
    res.json(await storage.getUsers());
  });

  // ── Admin User Management ────────────────────────────────────────
  function requireAdmin(req: any, res: any, next: any) {
    if (!req.session?.userId) return res.status(401).json({ message: "Not authenticated" });
    const role = (req.session as any).globalRole || "";
    if (!["master_admin", "admin"].includes(role)) {
      return res.status(403).json({ message: "Admin access required" });
    }
    next();
  }

  app.get("/api/admin/users", requireAuth, requireAdmin, async (req, res) => {
    const allUsers = await db.select({
      id: users.id,
      name: users.name,
      email: users.email,
      role: users.role,
      globalRole: users.globalRole,
      status: users.status,
      userType: users.userType,
      department: users.department,
      jobTitle: users.jobTitle,
      mustChangePassword: users.mustChangePassword,
      permissions: users.permissions,
      createdAt: users.createdAt,
      lastLogin: users.lastLogin,
      suspendedAt: users.suspendedAt,
      suspendedReason: users.suspendedReason,
    }).from(users).orderBy(users.id);
    res.json(allUsers);
  });

  // PATCH /api/admin/users/:id/permissions — update granular access permissions
  const accessLevelSchema = z.enum(["none", "view", "edit"]);
  const permissionsBodySchema = z.object({
    crm: accessLevelSchema.optional(),
    partnerships: accessLevelSchema.optional(),
    projects: accessLevelSchema.optional(),
    communications: accessLevelSchema.optional(),
    team_workload: accessLevelSchema.optional(),
    knowledge: accessLevelSchema.optional(),
    support: accessLevelSchema.optional(),
    quoting: accessLevelSchema.optional(),
    calendar: accessLevelSchema.optional(),
    mail_team: z.record(z.string(), z.object({ view: z.boolean(), edit: z.boolean() })).optional(),
    calendar_team: z.array(z.number()).optional(),
  });
  app.patch("/api/admin/users/:id/permissions", requireAuth, requireAdmin, async (req, res) => {
    try {
      const actorId = (req.session as any).userId;
      const [actor] = await db.select({ role: users.globalRole }).from(users).where(eq(users.id, actorId)).limit(1);
      if (!actor || !["master_admin", "admin"].includes(actor.role)) {
        return res.status(403).json({ message: "Admin access required" });
      }
      const targetId = parseInt(req.params.id);
      if (isNaN(targetId)) return res.status(400).json({ message: "Invalid user ID" });
      const parsed = permissionsBodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid permissions payload", errors: parsed.error.issues });
      }
      const [updated] = await db.update(users).set({ permissions: parsed.data } as any).where(eq(users.id, targetId)).returning({ id: users.id, permissions: users.permissions });
      if (!updated) return res.status(404).json({ message: "User not found" });
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // GET /api/admin/team-accounts — shared email inboxes (for Access tab)
  app.get("/api/admin/team-accounts", requireAuth, requireAdmin, async (req, res) => {
    try {
      const accounts = await db.select({ id: emailAccounts.id, emailAddress: emailAccounts.emailAddress, displayName: emailAccounts.displayName })
        .from(emailAccounts).where(and(eq(emailAccounts.isShared, true), eq(emailAccounts.isActive, true)));
      res.json(accounts);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // GET /api/admin/team-members — active users (for calendar overlay list)
  app.get("/api/admin/team-members", requireAuth, requireAdmin, async (req, res) => {
    try {
      const members = await db.select({ id: users.id, name: users.name, email: users.email, globalRole: users.globalRole })
        .from(users).where(sql`status != 'suspended' AND status != 'deactivated'`).orderBy(users.name);
      res.json(members);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // GET /api/admin/auto-confirm/dry-run
  // Always runs in dry-run mode (never writes). Returns structured sweep report:
  // pipeline state, per-candidate gate decisions, and bucketed skip reasons.
  // Access: master_admin / admin only.
  app.get("/api/admin/auto-confirm/dry-run", requireAuth, requireAdmin, async (req, res) => {
    try {
      const report = await buildSweepReport(false); // false = honour dry-run flag (always safe)
      res.json(report);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // POST /api/admin/gmail/backfill-associations
  // Backfills email_associations for all email_messages that were inserted before
  // the association engine was active — i.e. messages with no association rows yet.
  //
  // Safety properties:
  //   - Admin-only.
  //   - No schema changes. No deletions. No destructive writes.
  //   - Idempotent: the engine skips any (emailMessageId, objectType, objectId)
  //     triplet that already exists, so re-running is always safe.
  //   - Sequential: messages are processed oldest-first (sent_at ASC) to preserve
  //     thread-bonus scoring (+25 when a thread is already marked "associated").
  //   - Per-message errors are caught and reported; processing always continues.
  //   - Access: master_admin / admin only.
  app.post("/api/admin/gmail/backfill-associations", requireAuth, requireAdmin, async (req, res) => {
    const startedAt = Date.now();

    try {
      // 1. Snapshot association count before so we can diff at the end.
      const beforeResult = await db.execute(sql`SELECT COUNT(*)::int AS count FROM email_associations`);
      const countBefore = Number((beforeResult.rows[0] as any)?.count ?? 0);

      // 2. Load all messages ordered oldest-first.
      //    sent_at is the canonical timestamp; fall back to created_at for messages
      //    where sent_at is null (should not happen in practice, but defensive).
      const messages = await db
        .select({
          id: emailMessages.id,
          gmailMessageId: emailMessages.gmailMessageId,
          ignoredReason: emailMessages.ignoredReason,
          sentAt: emailMessages.sentAt,
        })
        .from(emailMessages)
        .orderBy(emailMessages.sentAt);

      let examined = 0;
      let processed = 0;
      let skipped = 0;
      const failures: { id: number; gmailMessageId: string | null; error: string }[] = [];

      // 3. Process sequentially — never concurrent, preserves thread-level ordering.
      for (const msg of messages) {
        examined++;

        // Skip messages the engine would ignore anyway (saves unnecessary DB round-trips).
        if (msg.ignoredReason) {
          skipped++;
          continue;
        }

        try {
          await runAssociationEngine(msg.id);
          processed++;
        } catch (err: any) {
          failures.push({
            id: msg.id,
            gmailMessageId: msg.gmailMessageId,
            error: err.message ?? String(err),
          });
          // Always continue — one bad message must not abort the batch.
        }
      }

      // 4. Snapshot association count after to compute diff.
      const afterResult = await db.execute(sql`SELECT COUNT(*)::int AS count FROM email_associations`);
      const countAfter = Number((afterResult.rows[0] as any)?.count ?? 0);

      const elapsedMs = Date.now() - startedAt;

      res.json({
        ok: true,
        summary: {
          examined,
          processed,
          skipped,
          failed: failures.length,
          associationsBefore: countBefore,
          associationsAfter: countAfter,
          associationsCreated: countAfter - countBefore,
          elapsedMs,
        },
        failures,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // ╔══════════════════════════════════════════════════════════════════════╗
  // ║ Commit 8 — Admin diagnostic + recovery endpoints (operator-facing)   ║
  // ╠══════════════════════════════════════════════════════════════════════╣
  // ║ A 4-route admin surface for inspecting and recovering the unified-   ║
  // ║ inbox sync pipeline. Lets a master_admin / admin see every connected ║
  // ║ mailbox's sync state at a glance (last_webhook_at, last_incremental_ ║
  // ║ sync_at, watch expiration, in-flight backfill, message count, etc.), ║
  // ║ and trigger a fresh 365-day (1-year) backfill or a force-full-resync ║
  // ║ needing direct DB access or a deploy.                                ║
  // ║                                                                      ║
  // ║ Gated by `requireAuth, requireAdmin` — non-admin users get 403.      ║
  // ║ NEVER user-facing: the regular inbox UI does not call any of these.  ║
  // ║                                                                      ║
  // ║ Schema: ZERO changes. All sync state already lives ON the existing   ║
  // ║ `email_accounts` row (last_history_id, watch_expiration_at,          ║
  // ║ last_webhook_at, last_incremental_sync_at, incremental_event_count). ║
  // ║ Backfill state lives in the raw-SQL-managed `backfill_jobs` table    ║
  // ║ added in Commit 7. This commit only READS those tables and triggers  ║
  // ║ existing workers — `autoEnqueueBackfillForNewAccount` (canonical     ║
  // ║ enqueue helper, exported from gmail-oauth.ts) and `syncIncremental`  ║
  // ║ (gmail-incremental.ts).                                              ║
  // ╚══════════════════════════════════════════════════════════════════════╝

  // GET /api/admin/mailbox/diagnostics
  // System-wide overview: one row per active mailbox. Includes per-mailbox
  // sync freshness, watch expiration, in-flight + most-recent-terminal
  // backfill jobs, and stored message counts. Single round-trip to Postgres
  // (correlated subqueries instead of N+1 fetches).
  app.get("/api/admin/mailbox/diagnostics", requireAuth, requireAdmin, async (_req, res) => {
    try {
      const { isPushConfigured } = await import("./services/gmail-watch");
      const pushConfigured = isPushConfigured();
      const STALE_MS = 24 * 60 * 60 * 1000; // "stale webhook" = no push in 24h
      const now = Date.now();

      const accountsR = await db.execute(sql.raw(`
        SELECT
          a.id                                      AS "accountId",
          a.email_address                           AS "emailAddress",
          a.user_id                                 AS "userId",
          a.is_shared                               AS "isShared",
          a.is_active                               AS "isActive",
          a.auth_status                             AS "authStatus",
          a.sync_enabled                            AS "syncEnabled",
          a.sync_error_message                      AS "syncErrorMessage",
          a.last_sync_at                            AS "lastSyncAt",
          a.last_incremental_sync_at                AS "lastIncrementalSyncAt",
          a.last_webhook_at                         AS "lastWebhookAt",
          a.last_history_id                         AS "lastHistoryId",
          COALESCE(a.incremental_event_count, 0)    AS "incrementalEventCount",
          a.watch_expiration_at                     AS "watchExpirationAt",
          a.watch_history_id                        AS "watchHistoryId",
          a.watch_topic                             AS "watchTopic",
          (SELECT COUNT(*)::int FROM email_messages m WHERE m.source_account_id = a.id) AS "storedMessageCount",
          (SELECT MAX(m.sent_at)  FROM email_messages m WHERE m.source_account_id = a.id) AS "lastMessageAt",
          (SELECT COUNT(*)::int FROM backfill_jobs b WHERE b.email_account_id = a.id AND b.status IN ('pending','running','cancelling')) AS "queueDepth",
          (SELECT json_build_object(
              'jobId',         b.id,
              'status',        b.status,
              'processed',     COALESCE(b.processed, 0),
              'totalEstimate', b.total_estimate,
              'updatedAt',     b.updated_at
            )
            FROM backfill_jobs b
            WHERE b.email_account_id = a.id AND b.status IN ('pending','running','cancelling')
            ORDER BY b.id DESC LIMIT 1) AS "inflightBackfill",
          (SELECT json_build_object(
              'jobId',         b.id,
              'status',        b.status,
              'processed',     COALESCE(b.processed, 0),
              'totalEstimate', b.total_estimate,
              'updatedAt',     b.updated_at
            )
            FROM backfill_jobs b
            WHERE b.email_account_id = a.id AND b.status IN ('completed','cancelled','failed')
            ORDER BY b.id DESC LIMIT 1) AS "latestTerminalBackfill"
        FROM email_accounts a
        WHERE a.is_active = TRUE
        ORDER BY a.id ASC
      `)) as any;

      // Compute derived freshness fields server-side so operators don't have
      // to do timestamp math by hand. Raw timestamps remain in the payload
      // for anyone who wants them.
      const accounts = (accountsR.rows ?? []).map((r: any) => {
        const lastWebhookAt = r.lastWebhookAt ? new Date(r.lastWebhookAt).getTime() : null;
        const watchExp      = r.watchExpirationAt ? new Date(r.watchExpirationAt).getTime() : null;
        const webhookAgeMs  = lastWebhookAt ? (now - lastWebhookAt) : null;
        return {
          ...r,
          webhookStaleness: {
            ageMs:   webhookAgeMs,
            isStale: webhookAgeMs == null ? null : webhookAgeMs > STALE_MS,
          },
          watch: {
            expirationAt: r.watchExpirationAt,
            historyId:    r.watchHistoryId,
            topic:        r.watchTopic,
            isExpired:    watchExp == null ? null : watchExp < now,
            expiresInMs:  watchExp == null ? null : (watchExp - now),
          },
        };
      });

      res.json({
        ok: true,
        generatedAt: new Date().toISOString(),
        pushConfigured,
        staleThresholdMs: STALE_MS,
        accountCount: accounts.length,
        accounts,
      });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // GET /api/admin/mailbox/:id/diagnostics
  // Single-mailbox detail view. Same per-account fields as the overview,
  // plus the last 10 backfill_jobs rows for that account so operators can
  // trace history (especially useful when debugging "why is this user's
  // import taking so long?" — you see the full job timeline).
  app.get("/api/admin/mailbox/:id/diagnostics", requireAuth, requireAdmin, async (req, res) => {
    try {
      const accountId = parseInt(req.params.id, 10);
      if (!accountId || isNaN(accountId)) return res.status(400).json({ message: "Invalid mailbox id" });

      const acctR = await db.execute(sql.raw(`
        SELECT a.id AS "accountId", a.email_address AS "emailAddress", a.user_id AS "userId",
               a.is_shared AS "isShared", a.is_active AS "isActive", a.auth_status AS "authStatus",
               a.sync_enabled AS "syncEnabled", a.sync_error_message AS "syncErrorMessage",
               a.last_sync_at AS "lastSyncAt", a.last_incremental_sync_at AS "lastIncrementalSyncAt",
               a.last_webhook_at AS "lastWebhookAt", a.last_history_id AS "lastHistoryId",
               COALESCE(a.incremental_event_count, 0) AS "incrementalEventCount",
               a.watch_expiration_at AS "watchExpirationAt",
               a.watch_history_id AS "watchHistoryId",
               a.watch_topic AS "watchTopic",
               a.created_at AS "createdAt"
        FROM email_accounts a WHERE a.id = ${accountId} LIMIT 1
      `)) as any;
      const acct = acctR.rows?.[0];
      if (!acct) return res.status(404).json({ message: "Mailbox not found" });

      const [counts, lastMsg, recentBackfills] = await Promise.all([
        db.execute(sql.raw(`SELECT COUNT(*)::int AS count FROM email_messages WHERE source_account_id = ${accountId}`)),
        db.execute(sql.raw(`SELECT MAX(sent_at) AS at FROM email_messages WHERE source_account_id = ${accountId}`)),
        db.execute(sql.raw(`
          SELECT id AS "jobId", status, COALESCE(processed,0) AS processed, total_estimate AS "totalEstimate",
                 to_char(date_from,'YYYY-MM-DD') AS "dateFrom", to_char(date_to,'YYYY-MM-DD') AS "dateTo",
                 last_page_token AS "lastPageToken", error_message AS "errorMessage",
                 created_at AS "createdAt", updated_at AS "updatedAt"
          FROM backfill_jobs WHERE email_account_id = ${accountId}
          ORDER BY id DESC LIMIT 10
        `)),
      ]);

      const STALE_MS = 24 * 60 * 60 * 1000;
      const now = Date.now();
      const lastWebhookAt = acct.lastWebhookAt ? new Date(acct.lastWebhookAt).getTime() : null;
      const watchExp      = acct.watchExpirationAt ? new Date(acct.watchExpirationAt).getTime() : null;
      const webhookAgeMs  = lastWebhookAt ? (now - lastWebhookAt) : null;
      const { isPushConfigured } = await import("./services/gmail-watch");

      res.json({
        ok: true,
        generatedAt: new Date().toISOString(),
        pushConfigured: isPushConfigured(),
        staleThresholdMs: STALE_MS,
        account: {
          ...acct,
          storedMessageCount: Number((counts as any).rows?.[0]?.count ?? 0),
          lastMessageAt: (lastMsg as any).rows?.[0]?.at ?? null,
          webhookStaleness: { ageMs: webhookAgeMs, isStale: webhookAgeMs == null ? null : webhookAgeMs > STALE_MS },
          watch: {
            expirationAt: acct.watchExpirationAt, historyId: acct.watchHistoryId, topic: acct.watchTopic,
            isExpired: watchExp == null ? null : watchExp < now,
            expiresInMs: watchExp == null ? null : (watchExp - now),
          },
        },
        recentBackfills: (recentBackfills as any).rows ?? [],
      });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // POST /api/admin/mailbox/:id/trigger-backfill
  // Enqueue a fresh backfill for any mailbox. Reuses the canonical enqueue
  // helper from gmail-oauth.ts so the result is byte-identical to a
  // post-OAuth auto-enqueue (same 365-day / 1-year default, same special-address
  // override, same fire-and-forget worker).
  //
  // Body (all optional):
  //   { dateFrom?: "YYYY-MM-DD",  dateTo?: "YYYY-MM-DD" }
  // Query (optional):
  //   ?force=true — skip the in-flight idempotency guard. Reserved for the
  //                 rare case where an operator KNOWS the existing job is
  //                 zombied and needs a clean retry. Default false.
  //
  // Response:
  //   200 { ok, enqueued: true,  jobId, dateFrom, dateTo }   on success
  //   409 { message: "Not enqueued: in-flight job already exists" } if
  //       another job is already pending/running/cancelling and ?force is
  //       not set. (Operator should call /backfill/cancel first or pass
  //       ?force=true.)
  app.post("/api/admin/mailbox/:id/trigger-backfill", requireAuth, requireAdmin, async (req, res) => {
    try {
      const accountId = parseInt(req.params.id, 10);
      if (!accountId || isNaN(accountId)) return res.status(400).json({ message: "Invalid mailbox id" });

      const acctR = await db.execute(sql.raw(
        `SELECT id, user_id AS "userId", email_address AS "emailAddress" FROM email_accounts WHERE id = ${accountId} LIMIT 1`
      )) as any;
      const acct = acctR.rows?.[0];
      if (!acct) return res.status(404).json({ message: "Mailbox not found" });

      const force = String(req.query.force ?? "").toLowerCase() === "true";
      const dateFromOverride = typeof req.body?.dateFrom === "string" ? req.body.dateFrom : undefined;
      const dateToOverride   = typeof req.body?.dateTo   === "string" ? req.body.dateTo   : undefined;

      const dateRe = /^\d{4}-\d{2}-\d{2}$/;
      if (dateFromOverride && !dateRe.test(dateFromOverride)) return res.status(400).json({ message: "dateFrom must be YYYY-MM-DD" });
      if (dateToOverride   && !dateRe.test(dateToOverride))   return res.status(400).json({ message: "dateTo must be YYYY-MM-DD" });

      const { autoEnqueueBackfillForNewAccount } = await import("./gmail-oauth");
      const result = await autoEnqueueBackfillForNewAccount({
        accountId:   Number(acct.id),
        userId:      Number(acct.userId),
        emailAddress: acct.emailAddress ?? null,
        dateFromOverride,
        dateToOverride,
        skipIdempotencyCheck: force,
      });

      if (!result.enqueued) {
        // 409 means "conflict with existing in-flight job" — the operator
        // can resolve it by hitting /backfill/cancel first OR re-calling
        // this endpoint with ?force=true to override.
        // 500 means "actual enqueue/DB failure" — different signal so
        // operators can distinguish "your action was blocked" from "the
        // system broke and you should investigate".
        // (Architect-flagged SEV-LOW: response semantics were blurred.)
        const isConflict = (result.reason ?? "").includes("in-flight job already exists");
        return res
          .status(isConflict ? 409 : 500)
          .json({ ok: false, message: `Not enqueued: ${result.reason ?? "unknown"}` });
      }
      res.json({ ok: true, ...result });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // POST /api/admin/mailbox/:id/force-full-resync
  // "I don't trust the history cursor — start over" recovery endpoint.
  // Clears `email_accounts.last_history_id` (and `sync_error_message`) and
  // fires `syncIncremental(accountId)` asynchronously. With no historyId,
  // the sync function takes the SEED branch: shallow paginated sync via
  // `syncEmailAccount({ maxPages: 1 })` followed by a fresh
  // `users.getProfile().historyId` capture — exactly the same path used on
  // first OAuth completion.
  //
  // NOT destructive: existing email_messages rows are untouched. The only
  // mutation is on the email_accounts row itself.
  //
  // Query (optional):
  //   ?withBackfill=true — also enqueue a 1-year backfill (honors the
  //                        in-flight guard; will NOT skip-idempotency).
  app.post("/api/admin/mailbox/:id/force-full-resync", requireAuth, requireAdmin, async (req, res) => {
    try {
      const accountId = parseInt(req.params.id, 10);
      if (!accountId || isNaN(accountId)) return res.status(400).json({ message: "Invalid mailbox id" });

      const acctR = await db.execute(sql.raw(
        `SELECT id, user_id AS "userId", email_address AS "emailAddress" FROM email_accounts WHERE id = ${accountId} LIMIT 1`
      )) as any;
      const acct = acctR.rows?.[0];
      if (!acct) return res.status(404).json({ message: "Mailbox not found" });

      await db.execute(sql.raw(`
        UPDATE email_accounts
           SET last_history_id = NULL,
               sync_error_message = NULL,
               updated_at = NOW()
         WHERE id = ${accountId}
      `));

      // Fire the reseed asynchronously — do NOT block the response on a
      // potentially long-running shallow sync + profile fetch.
      const { syncIncremental } = await import("./services/gmail-incremental");
      syncIncremental(Number(acct.id))
        .catch((err) => console.error(`[admin force-full-resync] account=${accountId} reseed error:`, err?.message ?? err));

      let backfillResult: any = null;
      const withBackfill = String(req.query.withBackfill ?? "").toLowerCase() === "true";
      if (withBackfill) {
        const { autoEnqueueBackfillForNewAccount } = await import("./gmail-oauth");
        backfillResult = await autoEnqueueBackfillForNewAccount({
          accountId:    Number(acct.id),
          userId:       Number(acct.userId),
          emailAddress: acct.emailAddress ?? null,
          // For the +backfill case we DO honor the in-flight guard; if the
          // operator wants to force-skip they should hit /trigger-backfill?force=true
          // explicitly so the intent is unambiguous.
          skipIdempotencyCheck: false,
        });
      }

      res.json({
        ok: true,
        accountId,
        clearedHistoryId: true,
        reseedScheduled: true,
        backfill: backfillResult,
      });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  app.put("/api/admin/users/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const userId = parseInt(req.params.id);
      if (isNaN(userId)) return res.status(400).json({ message: "Invalid user ID" });

      const sessionUser = await db.select().from(users).where(eq(users.id, req.session.userId!)).limit(1);
      if (!sessionUser[0]) return res.status(401).json({ message: "Not authenticated" });
      const actorRole = sessionUser[0].globalRole;
      if (!["master_admin", "admin"].includes(actorRole)) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { name, email, globalRole, status, userType, department, jobTitle, suspendedReason } = req.body;

      // Only master_admin can set master_admin role
      if (globalRole === "master_admin" && actorRole !== "master_admin") {
        return res.status(403).json({ message: "Only Master Admin can assign Master Admin role" });
      }

      // Prevent demoting or suspending the last master_admin
      if (globalRole && globalRole !== "master_admin") {
        const [existing] = await db.select({ id: users.id, globalRole: users.globalRole }).from(users).where(eq(users.id, userId));
        if (existing?.globalRole === "master_admin") {
          const masterAdmins = await db.select({ id: users.id }).from(users).where(sql`global_role = 'master_admin'`);
          if (masterAdmins.length <= 1) {
            return res.status(400).json({ message: "Cannot demote the last Master Admin" });
          }
        }
      }

      const updateData: Record<string, unknown> = {};
      if (name !== undefined) updateData.name = name;
      if (email !== undefined) updateData.email = email.toLowerCase().trim();
      if (globalRole !== undefined) updateData.globalRole = globalRole;
      if (userType !== undefined) updateData.userType = userType;
      if (department !== undefined) updateData.department = department || null;
      if (jobTitle !== undefined) updateData.jobTitle = jobTitle || null;
      if (status !== undefined) {
        updateData.status = status;
        if (status === "suspended") {
          updateData.suspendedAt = new Date();
          updateData.suspendedReason = suspendedReason || null;
        } else if (status === "active") {
          updateData.suspendedAt = null;
          updateData.suspendedReason = null;
        }
      }

      const [updated] = await db.update(users).set(updateData as any).where(eq(users.id, userId)).returning();
      if (!updated) return res.status(404).json({ message: "User not found" });
      res.json(updated);
    } catch (err: any) {
      console.error("[admin/users PUT]", err);
      res.status(500).json({ message: err?.message || "Failed to update user" });
    }
  });

  // ---------------------------------------------------------------------------
  // Premium invite email builder — used by create-user and resend-invite routes.
  // Renders a branded HTML email matching VoltSafe Growth OS visual identity.
  // ---------------------------------------------------------------------------
  function buildInviteEmail(opts: {
    recipientName: string;
    recipientEmail: string;
    tempPassword: string;
    loginUrl: string;
    isResend: boolean;
  }): string {
    const { recipientName, recipientEmail, tempPassword, loginUrl, isResend } = opts;
    const firstName = recipientName.split(" ")[0] || recipientName;
    const headline = isResend ? "Your access has been refreshed" : "You've been invited";
    const subline = isResend
      ? `Hi ${firstName}, your VoltSafe Growth OS credentials have been reset. Use the details below to sign back in.`
      : `Hi ${firstName}, your account is ready. Use the credentials below to access VoltSafe Growth OS for the first time.`;

    return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>VoltSafe Growth OS</title>
</head>
<body style="margin:0;padding:0;background-color:#f0f2f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background-color:#f0f2f5;padding:40px 16px;">
    <tr>
      <td align="center">
        <!-- Card -->
        <table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="max-width:520px;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.08);">

          <!-- Teal header -->
          <tr>
            <td style="background-color:#0d9488;padding:28px 32px 26px;">
              <table cellpadding="0" cellspacing="0" border="0" role="presentation">
                <tr>
                  <td style="padding-right:14px;vertical-align:middle;">
                    <div style="width:44px;height:44px;background:rgba(255,255,255,0.18);border-radius:11px;text-align:center;line-height:44px;font-size:24px;">&#9875;</div>
                  </td>
                  <td style="vertical-align:middle;">
                    <div style="font-size:19px;font-weight:700;color:#ffffff;letter-spacing:-0.3px;line-height:1.2;">VoltSafe Growth OS</div>
                    <div style="font-size:12px;color:rgba(255,255,255,0.65);margin-top:3px;letter-spacing:0.1px;">Where Prongless Power Meets Execution</div>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <!-- Body -->
          <tr>
            <td style="padding:32px 32px 8px;">
              <h1 style="margin:0 0 10px;font-size:22px;font-weight:700;color:#0f172a;letter-spacing:-0.4px;">${headline}</h1>
              <p style="margin:0 0 26px;font-size:15px;color:#64748b;line-height:1.65;">${subline}</p>

              <!-- Credentials box -->
              <table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;margin-bottom:26px;">
                <!-- Email row -->
                <tr>
                  <td style="padding:14px 18px;border-bottom:1px solid #e2e8f0;">
                    <div style="font-size:10.5px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.7px;margin-bottom:5px;">Email address</div>
                    <div style="font-size:14px;font-weight:500;color:#0f172a;">${recipientEmail}</div>
                  </td>
                </tr>
                <!-- Password row -->
                <tr>
                  <td style="padding:14px 18px;">
                    <div style="font-size:10.5px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.7px;margin-bottom:5px;">Temporary password</div>
                    <code style="display:inline-block;font-size:15px;font-weight:600;color:#0f172a;background:#f1f5f9;padding:5px 12px;border-radius:7px;border:1px solid #e2e8f0;letter-spacing:0.5px;">${tempPassword}</code>
                  </td>
                </tr>
              </table>

              <!-- CTA button -->
              <table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="margin-bottom:28px;">
                <tr>
                  <td align="center">
                    <a href="${loginUrl}" style="display:inline-block;background-color:#0d9488;color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:14px 40px;border-radius:10px;letter-spacing:-0.1px;">Sign in to VoltSafe &rarr;</a>
                  </td>
                </tr>
              </table>

              <p style="margin:0 0 28px;font-size:13px;color:#94a3b8;line-height:1.65;">You will be prompted to set a permanent password the first time you sign in. Keep these credentials private and do not share them.</p>
            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td style="background:#f8fafc;padding:16px 32px;border-top:1px solid #e2e8f0;">
              <p style="margin:0;font-size:12px;color:#94a3b8;line-height:1.5;">Sent by <strong style="color:#64748b;">VoltSafe Growth OS</strong> &middot; If you weren&rsquo;t expecting this, you can safely ignore it.</p>
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
  }

  app.post("/api/admin/users", requireAuth, requireAdmin, async (req, res) => {
    const sessionUser = await db.select().from(users).where(eq(users.id, req.session.userId!)).limit(1);
    if (!sessionUser[0]) return res.status(401).json({ message: "Not authenticated" });
    const actorRole = sessionUser[0].globalRole;
    if (!["master_admin", "admin"].includes(actorRole)) {
      return res.status(403).json({ message: "Admin access required" });
    }

    const { name, email, globalRole = "sales", userType = "internal", department, jobTitle } = req.body;
    if (!name || !email) return res.status(400).json({ message: "Name and email required" });

    const existing = await db.select().from(users).where(eq(users.email, email.toLowerCase().trim()));
    if (existing.length > 0) return res.status(409).json({ message: "Email already in use" });

    const tempPassword = Math.random().toString(36).slice(-10) + "Aa1!";
    const hashed = await hashPassword(tempPassword);

    const [created] = await db.insert(users).values({
      name,
      email: email.toLowerCase().trim(),
      password: hashed,
      role: "read-only",
      globalRole,
      status: "invited",
      userType,
      department: department || null,
      jobTitle: jobTitle || null,
      invitedBy: req.session.userId,
      mustChangePassword: true,
    }).returning();

    // Seed 4 default personal columns for the new user (non-blocking)
    const _defaultPersonalCols = [
      { slug: "my_col_1", label: "My Column 1", color: "blue"   },
      { slug: "my_col_2", label: "My Column 2", color: "violet" },
      { slug: "my_col_3", label: "My Column 3", color: "teal"   },
      { slug: "my_col_4", label: "My Column 4", color: "slate"  },
    ];
    Promise.all(_defaultPersonalCols.map((c, i) =>
      db.execute(sql`
        INSERT INTO user_task_columns (user_id, slug, label, color, sort_order)
        VALUES (${created.id}, ${c.slug}, ${c.label}, ${c.color}, ${i})
        ON CONFLICT (user_id, slug) DO NOTHING
      `)
    )).catch(() => {});

    // Send welcome email (non-blocking — user is created regardless of email success)
    const SYSTEM_SENDER_ID = 4; // Trevor's account used as the system sender
    const loginUrl = process.env.APP_URL || "https://image-linker-burgesstrevor76.replit.app";
    const welcomeHtml = buildInviteEmail({ recipientName: name, recipientEmail: email.toLowerCase().trim(), tempPassword, loginUrl, isResend: false });

    sendEmail(SYSTEM_SENDER_ID, email.toLowerCase().trim(), `You've been invited to VoltSafe Growth OS`, welcomeHtml)
      .catch((err) => console.error("[welcome-email] Failed to send welcome email to", email, err?.message));

    res.json({ ...created, tempPassword });
  });

  app.post("/api/admin/users/:id/resend-invite", requireAuth, requireAdmin, async (req, res) => {
    const userId = parseInt(req.params.id);
    const sessionUser = await db.select().from(users).where(eq(users.id, req.session.userId!)).limit(1);
    if (!sessionUser[0] || !["master_admin", "admin"].includes(sessionUser[0].globalRole)) {
      return res.status(403).json({ message: "Admin access required" });
    }
    const [target] = await db.select().from(users).where(eq(users.id, userId));
    if (!target) return res.status(404).json({ message: "User not found" });

    const tempPassword = Math.random().toString(36).slice(-10) + "Aa1!";
    const hashed = await hashPassword(tempPassword);
    await db.update(users).set({ password: hashed, mustChangePassword: true } as any).where(eq(users.id, userId));

    const SYSTEM_SENDER_ID = 4;
    const loginUrl = process.env.APP_URL || "https://image-linker-burgesstrevor76.replit.app";
    const welcomeHtml = buildInviteEmail({ recipientName: target.name, recipientEmail: target.email, tempPassword, loginUrl, isResend: true });

    sendEmail(SYSTEM_SENDER_ID, target.email, `Your VoltSafe Growth OS access has been refreshed`, welcomeHtml)
      .catch((err) => console.error("[resend-invite] Failed to send invite email to", target.email, err?.message));

    res.json({ message: "Invite resent" });
  });

  app.post("/api/admin/users/:id/suspend", requireAuth, requireAdmin, async (req, res) => {
    const userId = parseInt(req.params.id);
    const sessionUser = await db.select().from(users).where(eq(users.id, req.session.userId!)).limit(1);
    if (!sessionUser[0] || !["master_admin", "admin"].includes(sessionUser[0].globalRole)) {
      return res.status(403).json({ message: "Admin access required" });
    }
    const [target] = await db.select().from(users).where(eq(users.id, userId));
    if (!target) return res.status(404).json({ message: "User not found" });
    if (target.globalRole === "master_admin") {
      const masters = await db.select().from(users).where(eq(users.globalRole as any, "master_admin"));
      if (masters.length <= 1) return res.status(400).json({ message: "Cannot suspend the last Master Admin" });
    }
    const [updated] = await db.update(users).set({ status: "suspended", suspendedAt: new Date(), suspendedReason: req.body.reason || null }).where(eq(users.id, userId)).returning();
    res.json(updated);
  });

  app.post("/api/admin/users/:id/activate", requireAuth, requireAdmin, async (req, res) => {
    const userId = parseInt(req.params.id);
    const sessionUser = await db.select().from(users).where(eq(users.id, req.session.userId!)).limit(1);
    if (!sessionUser[0] || !["master_admin", "admin"].includes(sessionUser[0].globalRole)) {
      return res.status(403).json({ message: "Admin access required" });
    }
    const [updated] = await db.update(users).set({ status: "active", suspendedAt: null, suspendedReason: null }).where(eq(users.id, userId)).returning();
    res.json(updated);
  });

  app.post("/api/admin/users/:id/reset-password", requireAuth, requireAdmin, async (req, res) => {
    const userId = parseInt(req.params.id);
    const sessionUser = await db.select().from(users).where(eq(users.id, req.session.userId!)).limit(1);
    if (!sessionUser[0] || !["master_admin", "admin"].includes(sessionUser[0].globalRole)) {
      return res.status(403).json({ message: "Admin access required" });
    }
    const newPass = req.body.newPassword;
    if (!newPass || newPass.length < 6) return res.status(400).json({ message: "Password must be at least 6 characters" });
    const hashed = await hashPassword(newPass);
    await db.update(users).set({ password: hashed, mustChangePassword: true }).where(eq(users.id, userId));
    res.json({ message: "Password reset" });
  });

  app.delete("/api/admin/users/:id", requireAuth, requireAdmin, async (req, res) => {
    const userId = parseInt(req.params.id);
    const sessionUser = await db.select().from(users).where(eq(users.id, req.session.userId!)).limit(1);
    if (!sessionUser[0] || !["master_admin", "admin"].includes(sessionUser[0].globalRole)) {
      return res.status(403).json({ message: "Admin access required" });
    }
    if (userId === req.session.userId) {
      return res.status(400).json({ message: "You cannot delete your own account" });
    }
    const [target] = await db.select().from(users).where(eq(users.id, userId));
    if (!target) return res.status(404).json({ message: "User not found" });
    if (target.globalRole === "master_admin" && sessionUser[0].globalRole !== "master_admin") {
      return res.status(403).json({ message: "Only a master admin can delete another master admin" });
    }
    await db.delete(users).where(eq(users.id, userId));
    res.json({ message: "User deleted" });
  });

