  // ─── Stage 3 — Projects ─────────────────────────────────────────────────
  // ── Default certification milestone checklist ────────────────────────────────
  const CERT_MILESTONES = [
    "Define certification scope",
    "Confirm standards / requirements",
    "Prepare documentation package",
    "Build certification samples",
    "Ship samples to lab",
    "Lab intake confirmed",
    "Testing started",
    "Failure review",
    "Corrective action complete",
    "Retest complete",
    "Certification passed",
    "Certificate received",
  ];

  async function createCertMilestones(projectId: number) {
    for (let i = 0; i < CERT_MILESTONES.length; i++) {
      await db.execute(sql.raw(
        `INSERT INTO project_milestones (project_id, title, status, sort_order, created_at, updated_at) VALUES (${projectId}, '${CERT_MILESTONES[i].replace(/'/g, "''")}', 'pending', ${i}, NOW(), NOW())`
      ));
    }
  }

  function certSqlSets(body: Record<string, any>): string[] {
    const map: Record<string, string> = {
      certificationProgram: "certification_program",
      certificationScope: "certification_scope",
      productName: "product_name",
      productVersion: "product_version",
      productRevision: "product_revision",
      skuOrInternalCode: "sku_or_internal_code",
      certificationPriority: "certification_priority",
      testingLabName: "testing_lab_name",
      labContactName: "lab_contact_name",
      labContactEmail: "lab_contact_email",
      labContactPhone: "lab_contact_phone",
      certificationStandardCodes: "certification_standard_codes",
      targetMarket: "target_market",
      applicationSubmissionDate: "application_submission_date",
      plannedTestStartDate: "planned_test_start_date",
      actualTestStartDate: "actual_test_start_date",
      targetCompletionDate: "target_completion_date",
      actualCompletionDate: "actual_completion_date",
      certificationStatus: "certification_status",
      overallRisk: "overall_risk",
      launchBlocker: "launch_blocker",
      blockerSummary: "blocker_summary",
      lastStatusUpdate: "last_status_update",
      nextAction: "next_action",
      nextActionDueDate: "next_action_due_date",
      sampleUnitsRequired: "sample_units_required",
      sampleUnitsBuilt: "sample_units_built",
      sampleUnitsShipped: "sample_units_shipped",
      sampleUnitsReceivedByLab: "sample_units_received_by_lab",
      sampleSerialNumbers: "sample_serial_numbers",
      sampleNotes: "sample_notes",
      failureFound: "failure_found",
      failureSummary: "failure_summary",
      correctiveActionRequired: "corrective_action_required",
      correctiveActionSummary: "corrective_action_summary",
      retestRequired: "retest_required",
      retestDate: "retest_date",
      passDate: "pass_date",
      certificateIssueDate: "certificate_issue_date",
      certificateExpiryDate: "certificate_expiry_date",
      internalOwnerUserId: "internal_owner_user_id",
      engineeringOwner: "engineering_owner",
      operationsOwner: "operations_owner",
      linkedSupplier: "linked_supplier",
      linkedProductionBatch: "linked_production_batch",
      estimatedCertificationCost: "estimated_certification_cost",
      actualCertificationCost: "actual_certification_cost",
      budgetStatus: "budget_status",
      certificationDocLink: "certification_doc_link",
      testReportLink: "test_report_link",
      sharedDriveFolderLink: "shared_drive_folder_link",
      certificateFile: "certificate_file",
      complianceNotes: "compliance_notes",
      trackerSheetUrl: "tracker_sheet_url",
      trackerSheetConfig: "tracker_sheet_config",
      trackerSheetLastSynced: "tracker_sheet_last_synced",
      trackerAlertState: "tracker_alert_state",
    };
    const sets: string[] = [];
    for (const [k, v] of Object.entries(body)) {
      const col = map[k];
      if (!col) continue;
      if (v === null || v === undefined) sets.push(`${col} = NULL`);
      else if (typeof v === "boolean") sets.push(`${col} = ${v}`);
      else if (typeof v === "number") sets.push(`${col} = ${v}`);
      else sets.push(`${col} = '${String(v).replace(/'/g, "''")}'`);
    }
    return sets;
  }

  app.get("/api/projects", requirePermission("projects", "view"), async (req, res) => {
    try {
      const { type, status, accountId, certFilter } = req.query as Record<string, string>;
      const wheres: string[] = [];
      if (type) wheres.push(`p.type = '${type.replace(/'/g, "''")}'`);
      if (status) wheres.push(`p.status = '${status.replace(/'/g, "''")}'`);
      if (accountId) wheres.push(`p.account_id = ${parseInt(accountId)}`);
      // Cert-specific quick filters (Phase 2)
      if (certFilter) {
        wheres.push(`p.type = 'certification'`);
        if (certFilter === "blocked") wheres.push(`pc.launch_blocker = true`);
        else if (certFilter === "retest") wheres.push(`pc.retest_required = true AND pc.certification_status NOT IN ('Certified','Passed')`);
        else if (certFilter === "due_30") wheres.push(`pc.target_completion_date <= NOW() + INTERVAL '30 days' AND pc.target_completion_date > NOW() AND pc.certification_status NOT IN ('Certified','Passed','Cancelled')`);
        else if (certFilter === "cert_expiring") wheres.push(`pc.certificate_expiry_date <= NOW() + INTERVAL '90 days' AND pc.certificate_expiry_date > NOW()`);
        else if (certFilter === "passed") wheres.push(`pc.certification_status IN ('Passed','Certified')`);
      }
      const where = wheres.length ? `WHERE ${wheres.join(" AND ")}` : "";
      const rows = await db.execute(sql.raw(`
        SELECT p.*,
          pc.certification_status, pc.overall_risk, pc.launch_blocker,
          pc.target_completion_date AS cert_target_completion_date,
          pc.certification_program, pc.product_name, pc.next_action_due_date,
          pc.retest_required, pc.certificate_expiry_date
        FROM projects p
        LEFT JOIN project_certifications pc ON pc.project_id = p.id
        ${where}
        ORDER BY p.created_at DESC
      `));
      res.json((rows as any).rows ?? []);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // ── GET /api/projects/cert-summary (Phase 1 dashboard) — BEFORE /:id ─────────
  app.get("/api/projects/cert-summary", requirePermission("projects", "view"), async (req, res) => {
    try {
      const now = new Date();
      const statsRows = await db.execute(sql.raw(`
        SELECT
          COUNT(*)::int AS total,
          COUNT(*) FILTER (WHERE pc.launch_blocker = true)::int AS blocked,
          COUNT(*) FILTER (WHERE pc.retest_required = true AND pc.certification_status NOT IN ('Certified','Passed'))::int AS retest_required,
          COUNT(*) FILTER (WHERE pc.certification_status IN ('Certified','Passed'))::int AS certified,
          COUNT(*) FILTER (WHERE pc.certificate_expiry_date BETWEEN NOW() AND NOW() + INTERVAL '90 days')::int AS cert_expiring_90d,
          COUNT(*) FILTER (WHERE pc.failure_found = true AND pc.certification_status NOT IN ('Certified','Passed'))::int AS failure_open
        FROM projects p
        LEFT JOIN project_certifications pc ON pc.project_id = p.id
        WHERE p.type = 'certification'
      `));
      const stats = ((statsRows as any).rows ?? [])[0] ?? {};

      // Next action items due within 7 days
      const nextDueRows = await db.execute(sql.raw(`
        SELECT p.id, p.name, pc.next_action, pc.next_action_due_date, pc.certification_status, pc.overall_risk, pc.launch_blocker
        FROM projects p
        JOIN project_certifications pc ON pc.project_id = p.id
        WHERE p.type = 'certification'
          AND pc.next_action_due_date IS NOT NULL
          AND pc.next_action_due_date <= NOW() + INTERVAL '7 days'
          AND pc.certification_status NOT IN ('Certified','Passed','Cancelled')
        ORDER BY pc.next_action_due_date ASC
        LIMIT 5
      `));

      // Health breakdown (at_risk: failure/retest/overdue but not blocked)
      const healthRows = await db.execute(sql.raw(`
        SELECT
          COUNT(*) FILTER (WHERE
            pc.launch_blocker = false AND (
              (pc.retest_required = true AND pc.certification_status NOT IN ('Certified','Passed')) OR
              (pc.failure_found = true AND pc.certification_status NOT IN ('Certified','Passed')) OR
              (pc.target_completion_date < NOW() AND pc.certification_status NOT IN ('Certified','Passed','Cancelled'))
            )
          )::int AS at_risk,
          COUNT(*) FILTER (WHERE
            pc.launch_blocker = false AND NOT (
              (pc.retest_required = true AND pc.certification_status NOT IN ('Certified','Passed')) OR
              (pc.failure_found = true AND pc.certification_status NOT IN ('Certified','Passed')) OR
              (pc.target_completion_date < NOW() AND pc.certification_status NOT IN ('Certified','Passed','Cancelled'))
            ) AND pc.certification_status NOT IN ('Certified','Passed','Cancelled')
          )::int AS on_track
        FROM projects p
        LEFT JOIN project_certifications pc ON pc.project_id = p.id
        WHERE p.type = 'certification'
      `));
      const health = ((healthRows as any).rows ?? [])[0] ?? {};

      res.json({
        total: parseInt(stats.total ?? "0"),
        blocked: parseInt(stats.blocked ?? "0"),
        at_risk: parseInt(health.at_risk ?? "0"),
        on_track: parseInt(health.on_track ?? "0"),
        retest_required: parseInt(stats.retest_required ?? "0"),
        certified: parseInt(stats.certified ?? "0"),
        cert_expiring_90d: parseInt(stats.cert_expiring_90d ?? "0"),
        failure_open: parseInt(stats.failure_open ?? "0"),
        next_due_items: (nextDueRows as any).rows ?? [],
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

