  // ── GET /api/scores/hot-list ─────────────────────────────────────────────────
  app.get("/api/scores/hot-list", requireAuth, async (req, res) => {
    try {
      const limit = Math.min(parseInt(String(req.query.limit ?? 15)), 50);

      // Fetch top candidates from each category in parallel
      const [leadsR, oppsR, quotesR, deploysR, churnR] = await Promise.all([
        db.execute(sql.raw(`
          SELECT l.id, l.company AS name, l.source, l.contact_email, l.contact_phone, l.owner_user_id,
            l.deal_amount, l.estimated_slips_impacted, l.status, l.updated_at, l.next_step, l.est_close_date, l.region,
            (SELECT COUNT(*) FROM tasks t WHERE t.linked_object_type='lead' AND t.linked_object_id=l.id AND t.status NOT IN ('done','completed','dismissed') AND t.due_date < NOW()) AS overdue_tasks
          FROM leads l WHERE l.status NOT IN ('closed_won','closed_lost','disqualified','converted')
          ORDER BY l.updated_at DESC LIMIT 60
        `)),
        db.execute(sql.raw(`
          SELECT o.id, o.title AS name, o.stage, o.amount, o.owner_user_id, o.est_close_date, o.last_activity_date, o.is_stalled,
            o.champion_identified, o.economic_buyer_identified, o.decision_criteria_known, o.pain_clarity, o.risk_flags, o.forecast_category,
            (SELECT COUNT(*) FROM quotes q WHERE q.opportunity_id=o.id AND q.status NOT IN ('archived','declined')) AS quote_count,
            (SELECT COUNT(*) FROM tasks t WHERE t.linked_object_type='opportunity' AND t.linked_object_id=o.id AND t.status NOT IN ('done','completed','dismissed') AND t.due_date < NOW()) AS overdue_tasks
          FROM opportunities o WHERE o.stage NOT IN ('closed_won','closed_lost')
          ORDER BY o.updated_at DESC LIMIT 60
        `)),
        db.execute(sql.raw(`
          SELECT q.id, q.quote_number AS name, q.status, q.total, q.opportunity_id, q.owner_user_id, q.sent_at, q.valid_until, q.customer_name,
            (SELECT COUNT(*) FROM tasks t WHERE t.linked_object_type='quote' AND t.linked_object_id=q.id AND t.status NOT IN ('done','completed','dismissed')) AS task_count
          FROM quotes q WHERE q.status NOT IN ('archived','accepted','declined')
          ORDER BY q.updated_at DESC LIMIT 60
        `)),
        db.execute(sql.raw(`
          SELECT d.id, d.site_name AS name, d.status, d.deploy_number, d.owner_user_id, d.planned_start, d.actual_start, d.target_go_live, d.updated_at, d.blockers,
            (SELECT COUNT(*) FROM deployment_blockers b WHERE b.deployment_id=d.id AND b.status='open') AS open_blockers,
            (SELECT COUNT(*) FROM deployment_blockers b WHERE b.deployment_id=d.id AND b.status='open' AND b.severity='critical') AS critical_blockers
          FROM deployments d WHERE d.status NOT IN ('completed','live','cancelled')
          ORDER BY d.updated_at DESC LIMIT 60
        `)),
        db.execute(sql.raw(`
          SELECT cs.account_id AS id, a.name, cs.health_status, cs.health_score, cs.billing_status, cs.renewal_date,
            cs.status, cs.last_checkin_at, cs.expansion_potential, cs.churn_risk_flags, cs.arr,
            (SELECT COUNT(*) FROM tasks t WHERE t.linked_object_type='account' AND t.linked_object_id=cs.account_id AND t.status NOT IN ('done','completed','dismissed') AND t.due_date < NOW()) AS overdue_tasks
          FROM customer_subscriptions cs JOIN accounts a ON a.id = cs.account_id
          WHERE cs.status NOT IN ('cancelled','churned')
          ORDER BY cs.updated_at DESC LIMIT 60
        `)),
      ]);

      const hotList: HotListItem[] = [];

      for (const lead of leadsR.rows as any[]) {
        const s = scoreLeadQuality({
          source: lead.source, contactEmail: lead.contact_email, contactPhone: lead.contact_phone,
          ownerUserId: lead.owner_user_id, dealAmount: lead.deal_amount, estimatedSlipsImpacted: lead.estimated_slips_impacted,
          status: lead.status, updatedAt: lead.updated_at, nextStep: lead.next_step, region: lead.region,
          overdueTaskCount: parseInt(lead.overdue_tasks ?? 0),
        });
        if (s.band === "high" || s.band === "critical") {
          hotList.push({ type: "lead", id: lead.id, name: lead.name, score: s, actionHint: actionHintFor("lead", s), link: `/leads/${lead.id}` });
        }
      }

      for (const opp of oppsR.rows as any[]) {
        const s = scoreOpportunityClose({
          stage: opp.stage, estCloseDate: opp.est_close_date, lastActivityDate: opp.last_activity_date,
          isStalled: opp.is_stalled, ownerUserId: opp.owner_user_id,
          championIdentified: opp.champion_identified, economicBuyerIdentified: opp.economic_buyer_identified,
          decisionCriteriaKnown: opp.decision_criteria_known, amount: opp.amount,
          hasQuote: parseInt(opp.quote_count ?? 0) > 0, painClarity: opp.pain_clarity,
          riskFlags: opp.risk_flags, forecastCategory: opp.forecast_category,
          overdueTaskCount: parseInt(opp.overdue_tasks ?? 0),
        });
        if (s.band === "high" || s.band === "critical") {
          hotList.push({ type: "opportunity", id: opp.id, name: opp.name, score: s, actionHint: actionHintFor("opportunity", s), link: `/opportunities/${opp.id}` });
        }
      }

      for (const q of quotesR.rows as any[]) {
        const s = scoreQuoteFollowUpUrgency({
          status: q.status, sentAt: q.sent_at, validUntil: q.valid_until, total: q.total,
          opportunityId: q.opportunity_id, hasFollowUpTask: parseInt(q.task_count ?? 0) > 0, ownerUserId: q.owner_user_id,
        });
        if (s.band === "high" || s.band === "critical") {
          hotList.push({ type: "quote", id: q.id, name: `${q.name}${q.customer_name ? ` (${q.customer_name})` : ""}`, score: s, actionHint: actionHintFor("quote", s), link: `/quotes/${q.id}` });
        }
      }

      for (const dep of deploysR.rows as any[]) {
        const s = scoreDeploymentDelayRisk({
          status: dep.status, plannedStart: dep.planned_start, actualStart: dep.actual_start,
          targetGoLive: dep.target_go_live, ownerUserId: dep.owner_user_id, blockers: dep.blockers,
          openBlockerCount: parseInt(dep.open_blockers ?? 0), criticalBlockerCount: parseInt(dep.critical_blockers ?? 0),
          updatedAt: dep.updated_at,
        });
        if (s.band === "high" || s.band === "critical") {
          hotList.push({ type: "deployment", id: dep.id, name: dep.name, score: s, actionHint: actionHintFor("deployment", s), link: `/deployments/${dep.id}` });
        }
      }

      for (const sub of churnR.rows as any[]) {
        const flags = Array.isArray(sub.churn_risk_flags) ? sub.churn_risk_flags : (sub.churn_risk_flags ? JSON.parse(sub.churn_risk_flags) : []);
        const s = scoreChurnRisk({
          healthScore: sub.health_score, healthStatus: sub.health_status, billingStatus: sub.billing_status,
          renewalDate: sub.renewal_date, status: sub.status, lastCheckinAt: sub.last_checkin_at,
          expansionPotential: sub.expansion_potential, churnRiskFlags: flags, arr: sub.arr,
          overdueTaskCount: parseInt(sub.overdue_tasks ?? 0),
        });
        if (s.band === "high" || s.band === "critical") {
          hotList.push({ type: "churn", id: sub.id, name: sub.name, score: s, actionHint: actionHintFor("churn", s), link: `/accounts/${sub.id}` });
        }
      }

      hotList.sort((a, b) => bandRank(b.score.band) - bandRank(a.score.band) || b.score.score - a.score.score);
      res.json(hotList.slice(0, limit));
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // ── POST /api/scores/acknowledge — dismiss a score item for cooldown window ──
  app.post("/api/scores/acknowledge", requireAuth, async (req, res) => {
    try {
      const userId = req.session.userId as number;
      const { modelName, recordType, recordId } = req.body;
      if (!modelName || !recordType || !recordId) {
        return res.status(400).json({ message: "modelName, recordType, recordId required" });
      }
      const mn = String(modelName).replace(/'/g, "''").slice(0, 80);
      const rt = String(recordType).replace(/'/g, "''").slice(0, 80);
      const rid = Number(recordId);
      const expiresAt = new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString();
      const result = await db.execute(sql.raw(
        `INSERT INTO score_acknowledgments (user_id, model_name, record_type, record_id, acknowledged_at, expires_at)
         VALUES (${userId}, '${mn}', '${rt}', ${rid}, NOW(), '${expiresAt}')
         RETURNING id, user_id AS "userId", model_name AS "modelName", record_type AS "recordType",
                   record_id AS "recordId", acknowledged_at AS "acknowledgedAt", expires_at AS "expiresAt"`
      ));
      res.status(201).json((result as any).rows[0] ?? { acknowledged: true });
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // ── GET /api/scores/command-center-widgets ───────────────────────────────────
  app.get("/api/scores/command-center-widgets", requireAuth, async (req, res) => {
    try {
      const userId = req.session.userId as number;
      const TOP = 5;

      const [leadsR, oppsR, quotesR, deploysR, churnR, expansionR] = await Promise.all([
        db.execute(sql.raw(`
          SELECT l.id, l.company AS name, l.source, l.contact_email, l.contact_phone, l.owner_user_id,
            l.deal_amount, l.estimated_slips_impacted, l.estimated_pedestal_count, l.status,
            l.created_at, l.updated_at, l.next_step, l.est_close_date, l.region,
            (SELECT COUNT(*) FROM tasks t WHERE t.linked_object_type='lead' AND t.linked_object_id=l.id AND t.status NOT IN ('done','completed','dismissed') AND t.due_date < NOW()) AS overdue_tasks,
            (SELECT COUNT(*) FROM activities a WHERE a.linked_object_type='lead' AND a.linked_object_id=l.id) AS activity_count
          FROM leads l WHERE l.status NOT IN ('closed_won','closed_lost','disqualified','converted')
          ORDER BY l.updated_at DESC LIMIT 100
        `)),
        db.execute(sql.raw(`
          SELECT o.id, o.title AS name, o.stage, o.amount, o.owner_user_id, o.est_close_date,
            o.last_activity_date, o.is_stalled, o.champion_identified, o.economic_buyer_identified,
            o.decision_criteria_known, o.decision_process_known, o.pain_clarity, o.risk_flags,
            o.forecast_category,
            (SELECT COUNT(*) FROM quotes q WHERE q.opportunity_id=o.id AND q.status NOT IN ('archived','declined')) AS quote_count,
            (SELECT COUNT(*) FROM tasks t WHERE t.linked_object_type='opportunity' AND t.linked_object_id=o.id AND t.status NOT IN ('done','completed','dismissed') AND t.due_date < NOW()) AS overdue_tasks
          FROM opportunities o WHERE o.stage NOT IN ('closed_won','closed_lost')
          ORDER BY o.updated_at DESC LIMIT 100
        `)),
        db.execute(sql.raw(`
          SELECT q.*,
            (SELECT COUNT(*) FROM tasks t WHERE t.linked_object_type='quote' AND t.linked_object_id=q.id AND t.status NOT IN ('done','completed','dismissed')) AS task_count
          FROM quotes q WHERE q.status NOT IN ('archived')
          ORDER BY q.updated_at DESC LIMIT 100
        `)),
        db.execute(sql.raw(`
          SELECT d.*,
            (SELECT COUNT(*) FROM deployment_blockers b WHERE b.deployment_id=d.id AND b.status='open') AS open_blockers,
            (SELECT COUNT(*) FROM deployment_blockers b WHERE b.deployment_id=d.id AND b.status='open' AND b.severity='critical') AS critical_blockers,
            (SELECT COUNT(*) FROM commissioning_checkpoints c WHERE c.deployment_id=d.id AND c.status='pending') AS pending_checkpoints
          FROM deployments d WHERE d.status NOT IN ('completed','live','cancelled')
          ORDER BY d.updated_at DESC LIMIT 100
        `)),
        db.execute(sql.raw(`
          SELECT cs.*, a.name AS account_name, a.id AS account_id_raw,
            (SELECT COUNT(*) FROM tasks t WHERE t.linked_object_type='account' AND t.linked_object_id=cs.account_id AND t.status NOT IN ('done','completed','dismissed') AND t.due_date < NOW()) AS overdue_tasks
          FROM customer_subscriptions cs
          JOIN accounts a ON a.id = cs.account_id
          WHERE cs.status NOT IN ('cancelled','churned')
          ORDER BY cs.updated_at DESC LIMIT 200
        `)),
        db.execute(sql.raw(`
          SELECT a.*,
            cs.health_status, cs.health_score, cs.arr, cs.expansion_potential AS cs_expansion_potential,
            (SELECT COUNT(*) FROM opportunities o WHERE o.account_id=a.id AND o.stage NOT IN ('closed_won','closed_lost')) AS open_opps,
            (SELECT COUNT(*) FROM activities act WHERE act.linked_object_type='account' AND act.linked_object_id=a.id) AS activity_count
          FROM accounts a
          LEFT JOIN LATERAL (
            SELECT health_status, health_score, arr, expansion_potential
            FROM customer_subscriptions WHERE account_id = a.id ORDER BY updated_at DESC LIMIT 1
          ) cs ON true
          WHERE a.lead_status NOT IN ('closed_lost','disqualified')
          ORDER BY a.updated_at DESC LIMIT 200
        `)),
      ]);

      function addDelta(items: any[], modelName: string): Promise<any[]> {
        if (!items.length) return Promise.resolve(items);
        const ids = items.map(i => i.id).join(",");
        return db.execute(sql.raw(`
          SELECT DISTINCT ON (entity_id) entity_id, previous_score, previous_band
          FROM score_snapshots WHERE model_name = '${modelName}' AND entity_id IN (${ids})
          ORDER BY entity_id, recorded_at DESC
        `)).then(r => {
          const snapMap: Record<number, { previous_score: number | null; previous_band: string | null }> = {};
          for (const row of r.rows as any[]) snapMap[row.entity_id] = { previous_score: row.previous_score, previous_band: row.previous_band };
          return items.map(item => {
            const snap = snapMap[item.id];
            const delta = snap?.previous_score != null ? item.score - snap.previous_score : null;
            return { ...item, delta, previousScore: snap?.previous_score ?? null, previousBand: snap?.previous_band ?? null };
          });
        });
      }

      const scoredLeads = (leadsR.rows as any[]).map(lead => {
        const score = scoreLeadQuality({
          source: lead.source, contactEmail: lead.contact_email, contactPhone: lead.contact_phone,
          ownerUserId: lead.owner_user_id, dealAmount: lead.deal_amount,
          estimatedSlipsImpacted: lead.estimated_slips_impacted, estimatedPedestalCount: lead.estimated_pedestal_count,
          status: lead.status, createdAt: lead.created_at, updatedAt: lead.updated_at,
          nextStep: lead.next_step, estCloseDate: lead.est_close_date, region: lead.region,
          overdueTaskCount: parseInt(lead.overdue_tasks ?? 0), activityCount: parseInt(lead.activity_count ?? 0),
        });
        return { id: lead.id, name: lead.name, link: `/leads/${lead.id}`, suggestedAction: actionHintFor("lead", score), ...score };
      }).sort((a, b) => b.score - a.score).slice(0, TOP);

      const scoredOpps = (oppsR.rows as any[]).map(opp => {
        const score = scoreOpportunityClose({
          stage: opp.stage, estCloseDate: opp.est_close_date, lastActivityDate: opp.last_activity_date,
          isStalled: opp.is_stalled, ownerUserId: opp.owner_user_id,
          championIdentified: opp.champion_identified, economicBuyerIdentified: opp.economic_buyer_identified,
          decisionCriteriaKnown: opp.decision_criteria_known, decisionProcessKnown: opp.decision_process_known,
          amount: opp.amount, hasQuote: parseInt(opp.quote_count ?? 0) > 0, painClarity: opp.pain_clarity,
          riskFlags: opp.risk_flags, forecastCategory: opp.forecast_category,
          overdueTaskCount: parseInt(opp.overdue_tasks ?? 0),
        });
        return { id: opp.id, name: opp.name, amount: opp.amount, stage: opp.stage, link: `/pipeline/${opp.id}`, suggestedAction: actionHintFor("opportunity", score), ...score };
      }).sort((a, b) => b.score - a.score).slice(0, TOP);

      const scoredQuotes = (quotesR.rows as any[]).map(q => {
        const score = scoreQuoteFollowUpUrgency({
          status: q.status, sentAt: q.sent_at, validUntil: q.valid_until, total: q.total,
          opportunityId: q.opportunity_id, hasFollowUpTask: parseInt(q.task_count ?? 0) > 0,
          ownerUserId: q.owner_user_id,
        });
        return { id: q.id, name: q.quote_number, customerName: q.customer_name, total: q.total, link: `/quotes/${q.id}`, suggestedAction: actionHintFor("quote", score), ...score };
      }).sort((a, b) => b.score - a.score).slice(0, TOP);

      const scoredDeployments = (deploysR.rows as any[]).map(dep => {
        const score = scoreDeploymentDelayRisk({
          status: dep.status, plannedStart: dep.planned_start, actualStart: dep.actual_start,
          targetGoLive: dep.target_go_live, ownerUserId: dep.owner_user_id, blockers: dep.blockers,
          openBlockerCount: parseInt(dep.open_blockers ?? 0),
          criticalBlockerCount: parseInt(dep.critical_blockers ?? 0),
          pendingCheckpointCount: parseInt(dep.pending_checkpoints ?? 0),
          updatedAt: dep.updated_at, createdAt: dep.created_at,
        });
        return { id: dep.id, name: dep.site_name, deployNumber: dep.deploy_number, link: `/deployments/${dep.id}`, suggestedAction: actionHintFor("deployment", score), ...score };
      }).sort((a, b) => b.score - a.score).slice(0, TOP);

      const scoredChurn = (churnR.rows as any[]).map(sub => {
        const flags = Array.isArray(sub.churn_risk_flags) ? sub.churn_risk_flags : (sub.churn_risk_flags ? JSON.parse(sub.churn_risk_flags) : []);
        const score = scoreChurnRisk({
          healthScore: sub.health_score, healthStatus: sub.health_status, billingStatus: sub.billing_status,
          renewalDate: sub.renewal_date, status: sub.status, lastCheckinAt: sub.last_checkin_at,
          expansionPotential: sub.expansion_potential, churnRiskFlags: flags,
          mrr: sub.mrr, arr: sub.arr, contractTermMonths: sub.contract_term_months,
          overdueTaskCount: parseInt(sub.overdue_tasks ?? 0),
        });
        return { id: sub.account_id, name: sub.account_name, arr: sub.arr, link: `/accounts/${sub.account_id}`, suggestedAction: actionHintFor("churn", score), ...score };
      }).sort((a, b) => b.score - a.score).slice(0, TOP);

      const scoredExpansion = (expansionR.rows as any[]).map(acc => {
        const score = scoreExpansionLikelihood({
          expansionPlans: acc.expansion_plans, expansionNotes: acc.expansion_notes,
          expansionPotential: acc.cs_expansion_potential ?? (acc.expansion_notes ? "low" : "none"),
          contractedUnits: acc.contracted_units, installedUnits: acc.installed_units,
          voltsafeSlipsLive: acc.voltsafe_slips_live, slipCount: acc.slip_count, totalSlips: acc.total_slips,
          healthStatus: acc.health_status, healthScore: acc.health_score,
          priority: acc.priority, betaTester: acc.beta_tester,
          lastInteractionAt: acc.last_interaction_at, activityCount: parseInt(acc.activity_count ?? 0),
          openOpportunityCount: parseInt(acc.open_opps ?? 0), arr: acc.arr,
        });
        return { id: acc.id, name: acc.name, arr: acc.arr, link: `/accounts/${acc.id}`, suggestedAction: actionHintFor("expansion", score), ...score };
      }).sort((a, b) => b.score - a.score).slice(0, TOP);

      // Filter out items acknowledged by this user within their cooldown window
      const acksResult = await db.execute(sql.raw(
        `SELECT model_name AS "modelName", record_id AS "recordId"
         FROM score_acknowledgments
         WHERE user_id = ${userId} AND expires_at > NOW()`
      ));
      const ackedKeys = new Set(
        ((acksResult as any).rows ?? []).map((r: any) => `${r.modelName}:${r.recordId}`)
      );
      const filterAcked = (arr: any[], mn: string) =>
        arr.filter(i => !ackedKeys.has(`${mn}:${i.id}`));

      const [leadsWithDelta, oppsWithDelta, quotesWithDelta, deploysWithDelta, churnWithDelta, expansionWithDelta] = await Promise.all([
        addDelta(filterAcked(scoredLeads, "lead_quality"), "lead_quality"),
        addDelta(filterAcked(scoredOpps, "opportunity_close"), "opportunity_close"),
        addDelta(filterAcked(scoredQuotes, "quote_urgency"), "quote_urgency"),
        addDelta(filterAcked(scoredDeployments, "deployment_risk"), "deployment_risk"),
        addDelta(filterAcked(scoredChurn, "churn_risk"), "churn_risk"),
        addDelta(filterAcked(scoredExpansion, "expansion_likelihood"), "expansion_likelihood"),
      ]);

      res.json({
        hottestLeads: leadsWithDelta,
        closeOpps: oppsWithDelta,
        urgentQuotes: quotesWithDelta,
        deploymentRisks: deploysWithDelta,
        churnRisks: churnWithDelta,
        expansionReady: expansionWithDelta,
      });
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // ── Executive Digest & Alert Routes ─────────────────────────────────────────

  // Helper: get or create a user's digest config with role-based defaults
  async function getOrCreateDigestConfig(userId: number, role: string) {
    const existing = await db.execute(sql.raw(
      `SELECT id, user_id AS "userId", enabled, cadence, send_hour AS "sendHour", send_day_of_week AS "sendDayOfWeek",
              channels, sections, severity_threshold AS "severityThreshold", is_role_default AS "isRoleDefault",
              quiet_hours_start AS "quietHoursStart", quiet_hours_end AS "quietHoursEnd", alert_rules AS "alertRules", updated_at AS "updatedAt"
       FROM digest_configs WHERE user_id = ${userId} LIMIT 1`
    ));
    if ((existing as any).rows?.length) return (existing as any).rows[0];

    // Seed role-based defaults
    const roleKey = (role || "sales").toLowerCase();
    const sectionDefaults: Record<string, boolean> = {};
    for (const s of getSectionsForRole(roleKey)) sectionDefaults[s] = true;
    const channelJson = JSON.stringify(["in_app"]).replace(/'/g, "''");
    const sectionsJson = JSON.stringify(sectionDefaults).replace(/'/g, "''");
    const alertsJson = JSON.stringify(DEFAULT_ALERT_RULES).replace(/'/g, "''");
    const sendHour = roleKey === "ceo" || roleKey === "cfo" ? 7 : 8;

    await db.execute(sql.raw(
      `INSERT INTO digest_configs (user_id, enabled, cadence, send_hour, send_day_of_week, channels, sections, severity_threshold, is_role_default, quiet_hours_start, quiet_hours_end, alert_rules, updated_at)
       VALUES (${userId}, true, 'daily', ${sendHour}, 1, '${channelJson}'::jsonb, '${sectionsJson}'::jsonb, 'medium', true, 21, 7, '${alertsJson}'::jsonb, NOW())
       ON CONFLICT (user_id) DO NOTHING`
    ));
    const created = await db.execute(sql.raw(
      `SELECT id, user_id AS "userId", enabled, cadence, send_hour AS "sendHour", send_day_of_week AS "sendDayOfWeek",
              channels, sections, severity_threshold AS "severityThreshold", is_role_default AS "isRoleDefault",
              quiet_hours_start AS "quietHoursStart", quiet_hours_end AS "quietHoursEnd", alert_rules AS "alertRules", updated_at AS "updatedAt"
       FROM digest_configs WHERE user_id = ${userId} LIMIT 1`
    ));
    return (created as any).rows[0];
  }

  // GET /api/digest/config — get current user's digest config
  app.get("/api/digest/config", requireAuth, async (req, res) => {
    try {
      const userId = (req.session as any).userId as number;
      const role = String((req.session as any).globalRole || "sales");
      const config = await getOrCreateDigestConfig(userId, role);
      res.json({ config, availableSections: getSectionsForRole(role) });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // PUT /api/digest/config — update digest config
  app.put("/api/digest/config", requireAuth, async (req, res) => {
    try {
      const userId = (req.session as any).userId as number;
      const role = String((req.session as any).globalRole || "sales");
      await getOrCreateDigestConfig(userId, role);
      const { enabled, cadence, sendHour, sendDayOfWeek, channels, sections, severityThreshold, quietHoursStart, quietHoursEnd, alertRules } = req.body;
      const updates: string[] = ["updated_at = NOW()", "is_role_default = false"];
      if (enabled !== undefined) updates.push(`enabled = ${Boolean(enabled)}`);
      if (cadence) updates.push(`cadence = '${cadence === "weekly" ? "weekly" : "daily"}'`);
      if (sendHour !== undefined) updates.push(`send_hour = ${Math.min(23, Math.max(0, Number(sendHour)))}`);
      if (sendDayOfWeek !== undefined) updates.push(`send_day_of_week = ${Math.min(7, Math.max(1, Number(sendDayOfWeek)))}`);
      if (channels) updates.push(`channels = '${JSON.stringify(channels).replace(/'/g, "''")}'::jsonb`);
      if (sections) updates.push(`sections = '${JSON.stringify(sections).replace(/'/g, "''")}'::jsonb`);
      if (severityThreshold) updates.push(`severity_threshold = '${severityThreshold.replace(/'/g, "''")}'`);
      if (quietHoursStart !== undefined) updates.push(`quiet_hours_start = ${Number(quietHoursStart)}`);
      if (quietHoursEnd !== undefined) updates.push(`quiet_hours_end = ${Number(quietHoursEnd)}`);
      if (alertRules) updates.push(`alert_rules = '${JSON.stringify(alertRules).replace(/'/g, "''")}'::jsonb`);
      await db.execute(sql.raw(`UPDATE digest_configs SET ${updates.join(", ")} WHERE user_id = ${userId}`));
      const updated = await db.execute(sql.raw(
        `SELECT id, user_id AS "userId", enabled, cadence, send_hour AS "sendHour", send_day_of_week AS "sendDayOfWeek",
                channels, sections, severity_threshold AS "severityThreshold", is_role_default AS "isRoleDefault",
                quiet_hours_start AS "quietHoursStart", quiet_hours_end AS "quietHoursEnd", alert_rules AS "alertRules", updated_at AS "updatedAt"
         FROM digest_configs WHERE user_id = ${userId} LIMIT 1`
      ));
      res.json({ config: (updated as any).rows[0] });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // GET /api/digest/preview — compose and return a digest preview
  app.get("/api/digest/preview", requireAuth, async (req, res) => {
    try {
      const userId = (req.session as any).userId as number;
      const role = String((req.session as any).globalRole || "sales");
      const config = await getOrCreateDigestConfig(userId, role);
      const sections = config.sections as Record<string, boolean>;
      const enabledSections = Object.entries(sections).filter(([, v]) => v).map(([k]) => k) as DigestSection[];
      const finalSections = enabledSections.length ? enabledSections : getSectionsForRole(role);
      const digest = await composeDigest(userId, role, finalSections, config.severityThreshold as any);
      const html = formatDigestAsHtml(digest);
      const format = String(req.query.format || "json");
      if (format === "html") return res.send(html);
      if (format === "text") return res.send(formatDigestAsText(digest));
      res.json({ digest, html });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // POST /api/digest/send-now — manually trigger digest delivery
  app.post("/api/digest/send-now", requireAuth, async (req, res) => {
    try {
      const userId = (req.session as any).userId as number;
      const role = String((req.session as any).globalRole || "sales");
      const config = await getOrCreateDigestConfig(userId, role);
      const sections = config.sections as Record<string, boolean>;
      const enabledSections = Object.entries(sections).filter(([, v]) => v).map(([k]) => k) as DigestSection[];
      const finalSections = enabledSections.length ? enabledSections : getSectionsForRole(role);
      const digest = await composeDigest(userId, role, finalSections, config.severityThreshold as any);
      const channels: string[] = Array.isArray(config.channels) ? config.channels : ["in_app"];
      const runChannel = (req.body?.channel && channels.includes(req.body.channel)) ? req.body.channel : channels[0];

      let deliveredAt: Date | null = null;
      let status = "delivered";
      let errorMsg: string | null = null;

      // In-app delivery — create a notification
      if (runChannel === "in_app" || channels.includes("in_app")) {
        try {
          const bodyText = digest.summary + (digest.sections.length ? ` · ${digest.sections.length} sections.` : "");
          const dedupeKey = `digest-manual-${userId}-${new Date().toISOString().slice(0, 16)}`;
          await db.execute(sql.raw(
            `INSERT INTO notifications (user_id, type, title, body, severity, action_url, is_read, dedupe_key, expires_at, created_at)
             VALUES (${userId}, 'digest', '${digest.title.replace(/'/g, "''")}', '${bodyText.replace(/'/g, "''")}', 'medium', '/alerts-digest', false, '${dedupeKey}', NOW() + INTERVAL '7 days', NOW())`
          ));
          deliveredAt = new Date();
        } catch (e: any) { errorMsg = e.message; status = "failed"; }
      }

      // Email delivery — use Gmail integration if connected
      if (runChannel === "email" || channels.includes("email")) {
        try {
          const userRes = await db.execute(sql.raw(`SELECT email FROM users WHERE id = ${userId} LIMIT 1`));
          const userEmail = (userRes as any).rows?.[0]?.email;
          if (userEmail) {
            const html = formatDigestAsHtml(digest);
            await sendEmail(userId, userEmail, digest.title, html);
            deliveredAt = new Date();
          }
        } catch (e: any) {
          errorMsg = (errorMsg ? errorMsg + "; " : "") + `Email: ${e.message}`;
          if (status !== "delivered") status = "failed";
        }
      }

      // Log run
      const summaryJson = JSON.stringify({
        totalSignals: digest.totalSignals, highSeverity: digest.highSeverityCount,
        sections: digest.sections.map(s => s.key),
      }).replace(/'/g, "''");
      const sectionsJson = JSON.stringify(finalSections).replace(/'/g, "''");
      await db.execute(sql.raw(
        `INSERT INTO digest_runs (user_id, digest_type, status, channel, sections_sent, payload_summary, error_message, generated_at, delivered_at)
         VALUES (${userId}, 'manual', '${status}', '${runChannel}', '${sectionsJson}'::jsonb, '${summaryJson}'::jsonb, ${errorMsg ? `'${errorMsg.replace(/'/g, "''")}'` : "NULL"}, NOW(), ${deliveredAt ? `'${deliveredAt.toISOString()}'` : "NULL"})`
      ));

      res.json({ ok: status === "delivered", status, digest: { title: digest.title, summary: digest.summary, sections: digest.sections.length } });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // GET /api/digest/runs — digest run history
  app.get("/api/digest/runs", requireAuth, async (req, res) => {
    try {
      const userId = (req.session as any).userId as number;
      const limit = Math.min(50, Number(req.query.limit) || 20);
      const rows = await db.execute(sql.raw(
        `SELECT id, user_id AS "userId", digest_type AS "digestType", status, channel,
                sections_sent AS "sectionsSent", payload_summary AS "payloadSummary",
                error_message AS "errorMessage", generated_at AS "generatedAt", delivered_at AS "deliveredAt"
         FROM digest_runs WHERE user_id = ${userId} ORDER BY generated_at DESC LIMIT ${limit}`
      ));
      res.json({ runs: (rows as any).rows ?? [] });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // GET /api/digest/role-defaults — available role default sections
  app.get("/api/digest/role-defaults", requireAuth, async (req, res) => {
    try {
      const role = String((req.session as any).globalRole || "sales");
      const sections = getSectionsForRole(role);
      res.json({ role, defaultSections: sections });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

